message.content:
{
  "description": "The creature is a quadrupedal animal with the overall body shape, dense shaggy fur, head, limbs and tail of a brown bear combined with the dorsal exoskeleton and frontal horn of a rhinoceros beetle. It stands in right-facing profile against a plain light background, covered in thick brown fur that is darker on the legs and lower body and lighter tan on the muzzle, with a bear-like head, small rounded ears, four sturdy legs ending in clawed paws, and a very small furry tail at the rear. Its back and shoulders are covered by a large, highly glossy dark reddish-brown to black chitinous structure, and a single large curved glossy horn with a forward-pointing tine projects upward and backward from its forehead.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like head with an elongated snout, black nose at the tip, small dark brown eyes, and a slightly open mouth with a lighter tan muzzle, covered in dense brown fur",
      "where": "at the front of the body, in profile facing to the right"
    },
    {
      "part": "horns",
      "looks_like": "one large glossy dark reddish-brown to black curved horn with a single pointed tine on its front edge, smooth and shiny with a chitinous texture, curving upward and backward",
      "where": "arising from the center of the forehead on top of the head"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears covered in dense fluffy brown fur",
      "where": "on top of the head behind the horn"
    },
    {
      "part": "legs",
      "looks_like": "four thick, muscular, heavily furred legs covered in long shaggy dark brown fur",
      "where": "beneath the body, two forelegs under the chest and two hindlegs under the hips, supporting the body in a standing posture"
    },
    {
      "part": "feet",
      "looks_like": "four large broad paws with visible blunt light-brown to dark claws on each toe",
      "where": "at the ends of the four legs, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "a very small short tuft of brown fur",
      "where": "at the extreme rear of the body on the left side, partially tucked under the rear edge of the shell"
    },
    {
      "part": "shell",
      "looks_like": "a large domed glossy dark brown shell with fine longitudinal ridges and strong reflective highlights, resembling beetle elytra, with a row of small circular holes along its lower edge where it meets the fur",
      "where": "covering the entire dorsal back and sides from behind the shoulders to above the hindquarters"
    },
    {
      "part": "plates",
      "looks_like": "a glossy dark reddish-brown shield-like plate with pointed spiky projections along its rear and side edges and a smooth reflective surface",
      "where": "covering the shoulder and neck area directly behind the head and immediately in front of the larger shell"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "rhinoceros beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0
}
